function check([root, k], actual) {
  if (typeof actual !== 'number') return false;
  const nodes = [{ val: root[0], links: [], children: 0 }];
  const order = [0];
  let head = 0;
  for (let i = 1; i < root.length; i += 2) {
    const parent = order[head++];
    for (const value of [root[i], root[i + 1]]) {
      if (value === null || value === undefined) continue;
      nodes.push({ val: value, links: [parent], children: 0 });
      nodes[parent].links.push(nodes.length - 1);
      nodes[parent].children++;
      order.push(nodes.length - 1);
    }
  }
  const from = nodes.findIndex(node => node.val === k);
  const dist = new Array(nodes.length).fill(-1);
  dist[from] = 0;
  const queue = [from];
  for (let q = 0; q < queue.length; q++) {
    for (const next of nodes[queue[q]].links) {
      if (dist[next] === -1) { dist[next] = dist[queue[q]] + 1; queue.push(next); }
    }
  }
  let nearest = Infinity;
  for (let i = 0; i < nodes.length; i++) if (nodes[i].children === 0) nearest = Math.min(nearest, dist[i]);
  const chosen = nodes.findIndex(node => node.val === actual);
  return chosen !== -1 && nodes[chosen].children === 0 && dist[chosen] === nearest;
}

