function validate([root, k]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  let count = 1;
  let slots = 2;
  for (let i = 1; i < root.length; i++) {
    if (slots === 0) return 'Some values have no parent in the level-order list.';
    slots--;
    if (root[i] !== null) {
      count++;
      slots += 2;
    }
  }
  if (count > 1000) return 'The tree has at most 1000 nodes.';
  const values = root.filter(v => v !== null);
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value is an integer between 1 and 1000.';
  if (new Set(values).size !== values.length) return 'All node values must be different.';
  if (!values.includes(k)) return 'k must be the value of a node in the tree.';
  return null;
}

