function findClosestLeaf(root, k) {
  const paths = [];
  const walk = (node, above) => {
    if (!node) return;
    const path = above.concat(node.val);
    paths.push({ node, path });
    walk(node.left, path);
    walk(node.right, path);
  };
  walk(root, []);
  const goal = paths.find(entry => entry.node.val === k).path;
  let answer = null;
  let shortest = Infinity;
  for (const { node, path } of paths) {
    if (node.left || node.right) continue;
    let shared = 0;
    while (shared < path.length && shared < goal.length && path[shared] === goal[shared]) shared++;
    const length = path.length + goal.length - 2 * shared;
    if (length < shortest) { shortest = length; answer = node.val; }
  }
  return answer;
}

